import torch


def _resolve_dtype(d):
    if isinstance(d, torch.dtype):
        return d
    return getattr(torch, str(d).replace("torch.", ""))


def run_correctness(inp, target, reduction):
    output = torch.binary_cross_entropy_with_logits(
        inp.float(), target.float(), reduction=reduction
    )
    return output.to(inp.dtype)


def run(inp, target, reduction):
    return torch.binary_cross_entropy_with_logits(
        inp, target, reduction=reduction
    )


def gen_inputs(ctx, device):
    shape = ctx["target__shape"]
    dtype = _resolve_dtype(ctx["target__dtype"])
    return {"target": torch.rand(shape, dtype=dtype, device=device)}
